impl flatbuffers::Verifiable for IPCMessage<'_> {
  #[inline]
  fn run_verifier(
    v: &mut flatbuffers::Verifier, pos: usize
  ) -> Result<(), flatbuffers::InvalidFlatbuffer> {
    use self::flatbuffers::Verifiable;
    v.visit_table(pos)?
     .visit_field::<flatbuffers::ForwardsUOffset<&str>>("id", Self::VT_ID, false)?
     .visit_union::<IPCMessagePayload, _>("payload_type", Self::VT_PAYLOAD_TYPE, "payload", Self::VT_PAYLOAD, false, |key, v, pos| {
        match key {
          IPCMessagePayload::NodeExecutionRequest => v.verify_union_variant::<flatbuffers::ForwardsUOffset<NodeExecutionRequest>>("IPCMessagePayload::NodeExecutionRequest", pos),
          IPCMessagePayload::NodeExecutionResponse => v.verify_union_variant::<flatbuffers::ForwardsUOffset<NodeExecutionResponse>>("IPCMessagePayload::NodeExecutionResponse", pos),
          _ => Ok(()),
        }
     })?
     .finish();
    Ok(())
  }
}
